import { describe, expect, it } from 'vitest'
import { slugify, transliteratePersian } from './slug'

/**
 * SS-254 parity fixtures — the client port must match the server slugifier
 * (`apps/api/src/modules/products/slug.ts`) byte-for-byte.
 *
 * The expected values below were GENERATED by executing the server
 * implementation (2026-10-26) — never written by hand:
 *
 *   cd apps/api && pnpm exec tsx -e "
 *     import { slugify } from './src/modules/products/slug';
 *     for (const v of [ ...vectors... ]) console.log(JSON.stringify([v, slugify(v)]))"
 *
 * If a vector ever fails, the server slugger changed: regenerate, review the
 * diff against `slug.spec.ts` (the server's own pins), and update these
 * fixtures intentionally — do not "fix" the port by guessing.
 */
const PARITY_VECTORS: ReadonlyArray<readonly [string, string]> = [
  ['سلام', 'slam'],
  ['کالای دیجیتال', 'kalay-dyjytal'],
  ['لپتاپ', 'lptap'],
  ['دل', 'dl'],
  [
    'هارد اکسترنال ای دیتا مدل HD710 Pro ظرفیت 1 ترابایت',
    'hard-akstrnal-ay-dyta-mdl-hd710-pro-zrfyt-1-trabayt',
  ],
  // ZWNJ (U+200C) dropped.
  ['می\u200Cشود', 'myshvd'],
  // Persian digits folded.
  ['XPS ۱۳', 'xps-13'],
  // Whitespace/punctuation runs collapse to one hyphen.
  ['Dell XPS   13 -- Pro', 'dell-xps-13-pro'],
  // Edge hyphens trimmed.
  ['--hello--', 'hello'],
  // Nothing slug-worthy survives.
  ['!!!', ''],
  // Live imported catalog slug (lossy by design — never rewritten).
  [
    'آبمیوه\u200Cگیری پرودو مدل PD-LFST123-BK',
    'abmyvhgyry-prvdv-mdl-pd-lfst123-bk',
  ],
  // Digraphs چ→ch, خ→kh, ی→y, ط→t.
  ['چرخ خیاطی', 'chrkh-khyaty'],
  // Mixed Persian/English with Persian digits.
  ['پاوربانک Green Lion ۲۰۰۰۰', 'pavrbank-green-lion-20000'],
  // ه→h folding inside a real product-style name.
  [
    'کارت حافظه SanDisk ۶۴ گیگابایت Ultra',
    'kart-hafzh-sandisk-64-gygabayt-ultra',
  ],
  // Live seeded product slug.
  ['ماوس گیمینگ پرووان مدل BOLT PMG55', 'mavs-gymyng-prvvan-mdl-bolt-pmg55'],
  // 255-character cap (the trailing '-b' falls beyond the slice).
  [
    'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA ب',
    'a'.repeat(255),
  ],
]

describe('slugify parity with the server slugger (SS-254)', () => {
  for (const [input, expected] of PARITY_VECTORS) {
    it(`slugify(${JSON.stringify(input.slice(0, 40))}…) → ${expected.slice(0, 40)}`, () => {
      expect(slugify(input)).toBe(expected)
    })
  }

  it('is deterministic', () => {
    const input = 'کالای دیجیتال Dell XPS ۱۳'
    expect(slugify(input)).toBe(slugify(input))
  })

  it('leaves unknown characters to the sanitizer (Latin pass-through)', () => {
    expect(transliteratePersian('Dell XPS')).toBe('Dell XPS')
  })
})
